const data = $json;

let decision = null;
let reason = null;

switch (data.caseCategory) {

  case "PEDIDO_DEMORADO": {
    const currentDate = new Date(data.currentDate);
    const estimatedDate = new Date(data.estimatedDeliveryDate);

    const graceDays = Number(data.delayGraceDays || 0);

    const limitDate = new Date(estimatedDate);
    limitDate.setDate(limitDate.getDate() + graceDays);

    if (currentDate > limitDate) {
      decision = "ESCALAR";
      reason = "El pedido superó la fecha estimada de entrega.";
    } else {
      decision = "RESUELTO";
      reason = "El pedido todavía se encuentra dentro del plazo estimado de entrega.";
    }

    break;
  }

  case "PRODUCTO_DANADO": {
    const currentDate = new Date(data.currentDate);
    const deliveryDate = new Date(data.deliveryDate);

    const windowDays = Number(data.windowDays || 0);

    const limitDate = new Date(deliveryDate);
    limitDate.setDate(limitDate.getDate() + windowDays);

    if (currentDate <= limitDate) {
      decision = "RESUELTO";
      reason = "El reclamo por producto dañado se encuentra dentro del plazo permitido.";
    } else {
      decision = "ESCALAR";
      reason = "El reclamo por producto dañado fue realizado fuera del plazo permitido.";
    }

    break;
  }
case "GARANTIA": {
  const currentDate = new Date(data.currentDate);
  const orderDate = new Date(data.orderDate);

  const warrantyMonths = Number(data.warrantyMonths || 0);

  const limitDate = new Date(orderDate);
  limitDate.setMonth(limitDate.getMonth() + warrantyMonths);

  if (currentDate <= limitDate) {
    decision = "ESCALAR";
    reason = "El producto se encuentra dentro del período de garantía y requiere revisión humana.";
  } else {
    decision = "FUERA_DE_POLITICA";
    reason = "El período de garantía ya venció.";
  }

  break;
}

case "CAMBIO_DEVOLUCION": {
  const currentDate = new Date(data.currentDate);
  const deliveryDate = new Date(data.deliveryDate);

  const windowDays = Number(data.windowDays || 0);

  const limitDate = new Date(deliveryDate);
  limitDate.setDate(limitDate.getDate() + windowDays);

  // 1. Primero validamos el plazo
  if (currentDate > limitDate) {
    decision = "FUERA_DE_POLITICA";
    reason = "La solicitud de cambio o devolución fue realizada fuera del plazo permitido.";
    break;
  }

  // 2. Si la política exige paquete cerrado
  if (data.requiresPackageClosed === true) {
    const packageOpened = data.reportedCondition?.packageOpened;

    if (packageOpened === null || packageOpened === undefined) {
      decision = "FALTA_UN_DATO";
      reason = "Falta saber si el paquete fue abierto para aplicar la política de devolución.";

      if (!data.missingData.includes("packageOpened")) {
        data.missingData.push("packageOpened");
      }

      break;
    }

    if (packageOpened === true) {
      decision = "FUERA_DE_POLITICA";
      reason = "La política de devolución exige que el paquete permanezca cerrado.";
      break;
    }

    decision = "RESUELTO";
    reason = "La solicitud se encuentra dentro del plazo y el paquete permanece cerrado.";
    break;
  }

  // 3. Si la política exige producto sin uso
  if (data.requiresUnused === true) {
    const productUsed = data.reportedCondition?.productUsed;

    if (productUsed === null || productUsed === undefined) {
      decision = "FALTA_UN_DATO";
      reason = "Falta saber si el producto fue usado para aplicar la política de devolución.";

      if (!data.missingData.includes("productUsed")) {
        data.missingData.push("productUsed");
      }

      break;
    }

    if (productUsed === true) {
      decision = "FUERA_DE_POLITICA";
      reason = "La política de devolución exige que el producto no haya sido utilizado.";
      break;
    }

    decision = "RESUELTO";
    reason = "La solicitud se encuentra dentro del plazo y el producto no fue utilizado.";
    break;
  }

  // 4. Política sin condición adicional
  decision = "RESUELTO";
  reason = "La solicitud se encuentra dentro del plazo permitido.";

  break;
}

case "PRODUCTO_INCORRECTO": {
  const expected = data.orderItem || {};
  const reported = data.reportedAttributes || {};

  const comparableAttributes = [
    "origin",
    "size",
    "format",
    "grind"
  ];

  const comparedAttributes = [];
  const mismatches = [];

  // Normalizamos strings para evitar diferencias irrelevantes
  const normalize = (value) => {
    if (value === null || value === undefined) {
      return null;
    }

    if (typeof value === "string") {
      return value.trim().toLowerCase();
    }

    return value;
  };

  for (const attribute of comparableAttributes) {
    // Solo comparamos atributos que el cliente realmente reportó
    if (
      Object.prototype.hasOwnProperty.call(reported, attribute) &&
      reported[attribute] !== undefined
    ) {
      const expectedValue = normalize(expected[attribute]);
      const reportedValue = normalize(reported[attribute]);

      comparedAttributes.push(attribute);

      if (expectedValue !== reportedValue) {
        mismatches.push(attribute);
      }
    }
  }

  // No hay información suficiente para comparar
  if (comparedAttributes.length === 0) {
    decision = "ESCALAR";
    reason = "No fue posible validar el producto recibido contra los atributos registrados en el pedido.";
    break;
  }

  // Se confirmó al menos una diferencia
  if (mismatches.length > 0) {
    decision = "RESUELTO";
    reason = `Se confirmó una diferencia entre el pedido y el producto reportado en: ${mismatches.join(", ")}.`;
    break;
  }

  // Los atributos reportados coinciden
  decision = "RESUELTO";
  reason = "Los atributos reportados coinciden con los registrados en el pedido.";

  break;
}

  default:
    throw new Error(
      `La categoría ${data.caseCategory} todavía no está implementada en el motor de políticas.`
    );
}

// requiresHuman se deriva de decision
const requiresHuman = decision === "ESCALAR";

// prioridad
let priority = "NORMAL";

if (
  decision === "ESCALAR" &&
  data.customerType === "B2B" &&
  data.productType === "machine"
) {
  priority = "HIGH";
}

return [
  {
    json: {
      ...data,
      decision,
      priority,
      requiresHuman,
      reason
    }
  }
];

const data = $json.output;

let preliminaryDecision = null;
let preliminaryReason = null;
let needsPolicy = true;

// 1. FUERA_DE_ALCANCE
if (data.category === "FUERA_DE_ALCANCE") {
  preliminaryDecision = "RESUELTO";
  preliminaryReason = "La consulta está fuera del alcance de postventa.";
  needsPolicy = false;
}

// 2. Falta orderId
else if (!data.orderId) {
  preliminaryDecision = "FALTA_UN_DATO";
  preliminaryReason = "Falta orderId para consultar el pedido.";
  needsPolicy = false;
}

// 3. Tool ejecutada pero pedido no encontrado
else if (
  data.toolResult &&
  data.toolResult.found === false
) {
  preliminaryDecision = "ESCALAR";
  preliminaryReason = "El orderId fue proporcionado pero el pedido no fue encontrado.";
  needsPolicy = false;
}

// 4. Caso válido para seguir a políticas
else {
  needsPolicy = true;
}

return [
  {
    json: {
      ...$json,
      preliminaryDecision,
      preliminaryReason,
      needsPolicy
    }
  }
];

const policies = $input.all().map(item => item.json);

// Obtenemos el caso que ya fue validado antes del IF
const caseData = $('Evaluar estado inicial').first().json;

// Tomamos el productType real desde el pedido
const productType =
  caseData.output.toolResult?.order?.items?.[0]?.productType ?? null;

// 1. Buscar política específica para el tipo de producto
let selectedPolicy = policies.find(
  policy =>
    policy.productType === productType &&
    policy.active === true
);

// 2. Si no existe una específica, buscar la política genérica "all"
if (!selectedPolicy) {
  selectedPolicy = policies.find(
    policy =>
      policy.productType === 'all' &&
      policy.active === true
  );
}

// 3. Si no existe ninguna política válida, detenemos la ejecución
if (!selectedPolicy) {
  throw new Error(
    `No se encontró una política activa para category=${caseData.output.category} y productType=${productType}`
  );
}

return [
  {
    json: selectedPolicy
  }
];
